import pandas as pd, numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv']
D={f:pd.read_csv(f).iloc[::4].reset_index(drop=True) for f in files}
def lag(u,T,dt):
    a=np.exp(-dt/T); return lfilter([1-a],[1,-a],u)
def simQ(p,d):
    a,b,T1,c1,g1,g2=p
    t=d.time_s.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values
    V0=V[0]; Q0=d.reactive_power_pu.values[0]; dt=t[1]-t[0]
    u1=Vs-V0; u2=V-V0
    x1=lag(g1*u1+g2*u2,T1,dt)
    return Q0+a*u1+b*u2+c1*x1
def res(p,ds):
    return np.concatenate([simQ(p,d)-d.reactive_power_pu.values for d in ds])
ds=[D[f] for f in files[:4]]
for T1 in [0.05,0.5,3]:
  pass
best=None
for T1 in [0.1,1,5]:
    p0=[0,0,T1,1,1,-1]
    def rr(p): return res([p[0],p[1],p[2],p[3],p[4],p[5]],ds)
    r=least_squares(rr,p0,bounds=([-5,-5,1e-3,-50,-50,-50],[5,5,50,50,50,50]))
    print(T1, r.x.round(4), np.std(r.fun).round(5), 'DCu1',(r.x[0]+r.x[3]*r.x[4]*r.x[2]).round(3),'DCu2',(r.x[1]+r.x[3]*r.x[5]*r.x[2]).round(3))
    if best is None or r.cost<best.cost: best=r
